#!/bin/bash
mkdir -p /opt/fleet/tune
if [ -f /opt/fleet/tune/tunealive.txt ]; then
  echo "RESET previous bench $(cat /opt/fleet/tune/tunealive.txt)"
  pkill -9 -f 'fleet/tune/tuneall.sh' 2>/dev/null; pkill -9 -x krig-miner 2>/dev/null
  pkill -9 -f 'pm-bench|srb-bench' 2>/dev/null; pkill -9 -f 'tune/SRBMiner|tune/peakminer' 2>/dev/null
  sleep 2
  [ -s /opt/fleet/tune/cron.bak ] && crontab /opt/fleet/tune/cron.bak 2>/dev/null && echo "crontab restored"
  for u in $(cat /opt/fleet/tune/units.txt 2>/dev/null); do systemctl start $u >/dev/null 2>&1; done
  rm -f /opt/fleet/tune/tunealive.txt /opt/fleet/tune/run/guard.stop
  sleep 2
fi
base64 -d > /opt/fleet/tune/tuneall.sh <<'B64'

B64
chmod +x /opt/fleet/tune/tuneall.sh
date -u +%FT%TZ > /opt/fleet/tune/tunealive.txt
nohup setsid bash /opt/fleet/tune/tuneall.sh >/opt/fleet/tune/launch.out 2>&1 &
sleep 12
echo "TUNE LAUNCHED $(hostname) n=$(nvidia-smi -L|grep -c '^GPU ') ts=$(date -u +%FT%TZ)"
tail -6 /opt/fleet/tune/tune.log 2>/dev/null
